package dev.codex.lastzhelper;
import java.io.*;import java.nio.file.*;import org.json.*;
public final class RecoveryStorageTests {
 static int checks;static final String UID="2059765822000064";static void expect(boolean v,String m){if(!v)throw new AssertionError(m);checks++;}
 interface Checked{void run()throws Exception;}static void rejects(Checked run)throws Exception{boolean bad=false;try{run.run();}catch(Exception e){bad=true;}expect(bad,"invalid operation rejected");}
 public static void main(String[] args)throws Exception{
  File dir=Files.createTempDirectory("lastz-recovery-fixture-").toFile();
  try{
   File state=new File(dir,"recovery.json");RecoveryState r=new RecoveryState(state);expect(r.attempts(UID,"vip")==0,"fresh retry budget");expect(r.retry(UID,"vip","transient",1000)==3000,"first retry persisted");r=new RecoveryState(state);expect(r.attempts(UID,"vip")==1,"restart retains attempt");expect(r.retry(UID,"vip","transient",2000)==12000,"second backoff");r=new RecoveryState(state);expect(r.retry(UID,"vip","transient",3000)==33000,"third backoff");RecoveryState full=r;rejects(()->full.retry(UID,"vip","transient",4000));expect(new RecoveryState(state).attempts(UID,"vip")==3,"rejected fourth attempt leaves budget intact");
   r.defer(UID,"vip","failed",5000);expect(new RecoveryState(state).deferred(UID,"vip")==905000,"cooldown survives reload");r.allowEpisode(UID,"vip",904999);expect(r.attempts(UID,"vip")==3,"cannot reset budget early");r.allowEpisode(UID,"vip",905000);expect(r.attempts(UID,"vip")==0,"new episode after cooldown");
   expect(r.restart(UID,1000)&&r.restart(UID,2000)&&r.restart(UID,3000),"three controlled restarts");expect(!new RecoveryState(state).restart(UID,4000),"restarts do not reset budget");expect(!r.restart(UID,500),"backward wall clock does not erase budget");expect(r.restart(UID,1801001),"restart window eventually permits recovery");r.deferAccount(UID,5000);expect(new RecoveryState(state).accountUntil(UID)==905000,"account cooldown survives worker restart");
   r.retry(UID,"alliance_help","transient",1000);r.success(UID,"alliance_help");expect(r.attempts(UID,"alliance_help")==0&&r.step(UID,"alliance_help").getLong("nextRetryMs")==0,"verified progress resets step");expect(r.deferred(UID,"vip")==0,"features isolated");
   File marker=new File(dir,"legacy-input.json");ControllerOwnership.check(marker);RotationFiles.write(marker,new JSONObject().put("schema",1).put("pending",false));ControllerOwnership.check(marker);checks++;RotationFiles.write(marker,new JSONObject().put("schema",1).put("pending",true));rejects(()->ControllerOwnership.check(marker));RotationFiles.write(marker,new JSONObject().put("schema",999).put("pending",false));rejects(()->ControllerOwnership.check(marker));
   RunRequest request=new RunRequest(dir,()->"boot-A");File stop=new File(dir,"stop");JSONObject options=new JSONObject().put("dryRun",false);String first=request.begin(options);expect(options.getString("runGeneration").equals(first),"worker carries run generation");expect(new RunRequest(dir,()->"boot-A").active(first,stop),"active consent reloads");expect(!new RunRequest(dir,()->"boot-B").active(first,stop),"no auto-resume after phone reboot");expect(!request.active("wrong-generation",stop),"stale worker blocked");
   expect(request.restart(first,stop)&&request.restart(first,stop)&&request.restart(first,stop),"bounded worker recovery");expect(!new RunRequest(dir,()->"boot-A").restart(first,stop),"worker restart budget survives app process");new RunRequest(dir,()->"boot-A").stop();expect(!request.active(first,stop)&&!request.restart(first,stop),"STOP revokes queued recovery");String second=request.begin(new JSONObject());request.finish(first);expect(request.active(second,stop),"old worker cannot cancel a newer run");stop.createNewFile();expect(!request.active(second,stop)&&!request.restart(second,stop),"STOP file independently fences recovery");stop.delete();request.finish(second);expect(!request.active(second,stop),"completed preview cannot restart");
   RotationShortcut route=new RotationShortcut("Fixture","com.lbe.parallel.intl/com.lbe.parallel.ui.LaunchDelegateActivity","com.lbe.parallel.ACTION_LAUNCH_PACKAGE",1);File profiles=new File(dir,"profiles.json");RotationProfiles p=new RotationProfiles(profiles);p.enroll(route,new JSONObject().put("accountUid",UID).put("accountName","Fixture"));JSONObject account=p.profiles.getJSONObject(0);expect(!account.getBoolean("selected"),"default features do not select accounts");for(String f:RotationPolicy.FEATURES)expect(account.getJSONObject("features").getBoolean(f),"new feature default enabled "+f);
   account.getJSONObject("features").put("vip",false).remove("alliance_help");p.save();RotationProfiles migrated=new RotationProfiles(profiles);expect(!migrated.profiles.getJSONObject(0).getJSONObject("features").getBoolean("vip"),"saved opt-out preserved");expect(migrated.profiles.getJSONObject(0).getJSONObject("features").getBoolean("alliance_help"),"new missing capability defaults enabled");migrated.profiles.getJSONObject(0).getJSONObject("features").put("fake_feature",true);migrated.save();rejects(()->new RotationProfiles(profiles));
   System.out.println("Recovery/session/default storage: "+checks+" checks passed; no Android/game access");
  }finally{for(File f:dir.listFiles())f.delete();dir.delete();}
 }
}
